fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let mut low: usize = 0;
    let mut high: usize = v.len() - 1;

    while low < high {
        let mid = low + (high - low) / 2;

        if v[mid] < k {
            // Target must be in right half, excluding mid
            low = mid + 1;
        } else {
            // Target is in left half including mid
            high = mid;
        }
    }

    // When low == high, we've found the target index
    low
}